import { useContext } from 'react';
import { ConfigProvider } from '@arco-design/web-react';

export const usePrefixCls = (
  tag?: string,
  props?: {
    prefixCls?: string;
  }
) => {
  const { prefixCls } = useContext(ConfigProvider.ConfigContext);
  return `${props?.prefixCls || prefixCls}-${tag ?? ''}`;
};
